"""Opt-in prepared-pattern fitting inside the original complete patch guards.

The catalogue is shared data, selected by mesh topology and pin mask rather
than Street/junction identity. Boundaries and heights are still constructed by
the original source-driven graph. Unmatched or rejected fits use the unchanged
complete patch. This experiment is not installed in the public library.
"""
import hashlib

import bpy

from . import curved_quad_pattern_nodes as pattern
from .curved_quad_fair_nodes import assign_group
from .curved_quad_quality_patch_nodes import supports

c = pattern.c


def catalogue(entries, *, semantic=False, continuations=False, graded_transfer=False, repair_coarse=False, interpolation=False):
    """One evaluator for all patterns; entries contain key and two asset objects."""
    entries = tuple(entries)
    if not entries or len(entries) > 64 or len({key for key, _, _ in entries}) != len(entries):
        raise ValueError('Use a nonempty bounded catalogue with unique pattern keys')
    identity = hashlib.sha256('|'.join(key+'|'+ref.name+'|'+weights.name
        for key, ref, weights in entries).encode()).hexdigest()[:16]
    identity = ('semantic-affine-continuations-' if continuations else 'semantic-affine-')+identity if semantic else identity
    if interpolation:
        if not semantic: raise ValueError('Source interpolation requires semantic charts')
        identity = 'source-interpolation-v1-'+identity
    if graded_transfer:
        if not semantic: raise ValueError('Boundary grading requires semantic full-profile charts')
        identity = 'graded-v1-'+identity
    if repair_coarse:
        if not semantic: raise ValueError('Coarse correction requires semantic full-profile charts')
        identity = 'refined-v1-'+identity
        if graded_transfer: identity = 'consistent-grading-v1-'+identity
    name = 'Prochitecture Streets / Experimental quad pattern catalogue / '+identity
    if name in bpy.data.node_groups: return bpy.data.node_groups[name]
    g = c.Graph(name)
    g.socket('Geometry', 'NodeSocketGeometry')
    if semantic:
        from . import curved_quad_semantic_pattern_nodes as fitting
        for key in fitting.CONTEXT: g.socket(key, 'NodeSocketGeometry')
        g.socket('Radial Count', 'NodeSocketInt'); g.socket('Input Valid', 'NodeSocketBool')
    g.socket('Geometry', 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Valid', 'NodeSocketBool', 'OUTPUT')
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    source = inp.outputs['Geometry']; count = c._count(g, source)
    chosen = c._select(g, source, False); found = False
    # Catalogue priority is fixed. Small edits cannot reorder its candidates.
    for index, (key, reference, coefficients) in enumerate(entries):
        call = g.node('GeometryNodeGroup', 'Prepared XY response '+key[:12])
        call.node_tree = fitting.build(continuations=continuations, graded_transfer=graded_transfer,
                                      repair_coarse=repair_coarse,interpolation=interpolation) if semantic else pattern.build()
        g.bind(source, call.inputs['Geometry'])
        if semantic:
            for socket in (*fitting.CONTEXT, 'Radial Count', 'Input Valid'):
                g.bind(inp.outputs[socket], call.inputs[socket])
            for socket, prop in (('Pattern Rows', 'rows'), ('Pattern Radial', 'radial'), ('Pattern Sides', 'sides')):
                call.inputs[socket].default_value = reference['st_pattern_'+prop]
        else:
            call.inputs['Signed Coefficients'].default_value = True
            call.inputs['Reference Deformation'].default_value = True
        for socket, obj in (('Pattern', reference), ('Coefficients', coefficients)):
            info = g.node('GeometryNodeObjectInfo', socket+' asset'); info.transform_space = 'ORIGINAL'
            info.inputs['Object'].default_value = obj; g.bind(info.outputs['Geometry'], call.inputs[socket])
        # Avoid touching the dense response table for a mismatched vertex count.
        possible = (g.math('COMPARE', c._count(g, inp.outputs['Mouths']), reference['st_pattern_sides'])
                    if semantic else g.math('COMPARE', count, len(reference.data.vertices)))
        possible = possible*(1.-found)
        use = c.choose(g, possible, call.outputs['Valid'], False, 'BOOLEAN')
        geometry = c._store(g, call.outputs['Geometry'], 'st_cq_pattern_index', index, 'INT')
        chosen = c.choose(g, use, geometry, chosen, 'GEOMETRY')
        found = g.math('MAXIMUM', found, use)
    g.bind(chosen, out.inputs['Geometry']); g.bind(found, out.inputs['Valid'])
    g.g['st_pattern_keys'] = [key for key, _, _ in entries]
    return g.g


def build_semantic(original, entries, *, graded_transfer=False, repair_coarse=False,redistribute_stations=False,continuous_stations=False):
    """Fit only the ordinary full-profile cyclic family, with original fallback.

    The layout context supplies analytic boundary data. Replacing the descent
    group alone cannot provide that context. Unsupported layout families remain
    unchanged; no fixture identity or current fine vertex count selects assets.
    Optional centered station redistribution keeps side counts, all analytic
    records and mouth profiles, with the existing complete curb-change bound.
    Its continuous option removes the finite activation jump at the short-gap
    cutoff; it is not a certificate for all station/pattern selection changes.
    """
    if not supports(original): raise ValueError('Require a complete framed original patch')
    if continuous_stations and not redistribute_stations:raise ValueError('Continuous stations require redistribution')
    entries = tuple(entries)
    library = catalogue(entries, semantic=True, graded_transfer=graded_transfer, repair_coarse=repair_coarse,
                        interpolation='Exact entrance rays v1' in original.name)
    identity = hashlib.sha256((original.name+'|'+library.name+
        ('|centered-stations-v1' if redistribute_stations else '')+
        ('|continuous-stations-v1' if continuous_stations else '')).encode()).hexdigest()[:16]
    name = 'Prochitecture Streets / Checked semantic pattern v1 / '+identity
    if name in bpy.data.node_groups: return bpy.data.node_groups[name]
    memo = {}; changed = []

    def clone(tree):
        if tree.as_pointer() in memo: return memo[tree.as_pointer()]
        if redistribute_stations and tree.name == 'Prochitecture Streets / Paired curved quad stations v1':
            from . import curved_station_relocation_nodes
            result = curved_station_relocation_nodes.build(centered=True,continuous=continuous_stations)
            memo[tree.as_pointer()] = result
            return result
        eligible = (tree.name.startswith('Prochitecture Streets / Ordinary cyclic direct quad layout v1')
                    and 'Original Section ports v1' in tree.name
                    and not any(part in tree.name for part in ('Original span sides', 'Original chain sides', 'Direct strip center')))
        children = [(n.name, clone(n.node_tree)) for n in tree.nodes if n.type == 'GROUP' and n.node_tree]
        replacements = [(key, child) for key, child in children if child != tree.nodes[key].node_tree]
        result = tree.copy() if eligible or replacements else tree
        if result != tree:
            result.name = 'Prochitecture Streets / Semantic pattern dependency / '+hashlib.sha256(
                (tree.name+'|'+identity).encode()).hexdigest()[:16]
            for key, child in replacements: assign_group(result.nodes[key], child)
        if eligible:
            descents = [n for n in result.nodes if n.type == 'GROUP' and n.node_tree and
                        n.node_tree.name.startswith('Prochitecture Streets / Pinned curved quad descent v1')]
            plans = [n for n in result.nodes if n.type == 'GROUP' and n.node_tree and
                     n.node_tree.name.startswith('Prochitecture Streets / Ordinary cyclic quad counts v1')]
            inputs = [n for n in result.nodes if n.type == 'GROUP_INPUT']
            if len(descents) != 1 or len(plans) != 1 or len(inputs) != 1:
                raise ValueError('Unrecognized cyclic layout interface: '+tree.name)
            old = descents[0]; plan = plans[0]; inp = inputs[0]
            sources = [link.from_socket for link in old.inputs['Geometry'].links]
            destinations = [link.to_socket for link in old.outputs['Geometry'].links]
            if len(sources) != 1 or not destinations: raise ValueError('Unconnected planar descent')
            call = result.nodes.new('GeometryNodeGroup')
            call.node_tree = catalogue(entries, semantic=True, continuations='Curb continuations' in tree.name,
                                      graded_transfer=graded_transfer, repair_coarse=repair_coarse,
                                      interpolation='Exact entrance rays v1' in tree.name)
            call.label = 'Prepared cyclic pattern from current analytic pins'
            result.links.new(sources[0], call.inputs['Geometry'])
            for key in ('Sources', 'Mapping', 'Approaches', 'Corners', 'Mouths', 'Depths', 'Input Valid'):
                result.links.new(inp.outputs[key], call.inputs[key])
            result.links.new(plan.outputs['Geometry'], call.inputs['Plan'])
            result.links.new(plan.outputs['Radial Count'], call.inputs['Radial Count'])
            geometry = call.outputs['Geometry']
            if redistribute_stations:
                # Keep the existing complete, same-parameter outline bound.
                # The clearance and height tables retain all analytic breaks;
                # only the mesh station generator has changed.
                from . import curved_mesh_boundary_nodes
                bound = result.nodes.new('GeometryNodeGroup')
                bound.node_tree = curved_mesh_boundary_nodes.build(station_relocation=True,centered=True,continuous=continuous_stations,
                                                                  interpolation='Exact entrance rays v1' in tree.name)
                bound.label = 'Bound every point of the redistributed curb'
                for key in ('Sources','Mapping','Approaches','Corners','Mouths','Depths','Cell Size','Input Valid'):
                    result.links.new(inp.outputs[key],bound.inputs[key])
                result.links.new(inp.outputs['Depths'],bound.inputs['Spaced Depths'])
                record = result.nodes.new('GeometryNodeStoreNamedAttribute')
                record.data_type = 'FLOAT'; record.domain = 'POINT'
                record.inputs['Name'].default_value = 'st_cq_outline_change'
                result.links.new(geometry,record.inputs['Geometry'])
                result.links.new(bound.outputs['Maximum Difference'],record.inputs['Value'])
                gate = result.nodes.new('GeometryNodeSwitch');gate.input_type = 'GEOMETRY'
                gate.label = 'Retain unchanged 0.05 mm complete outline limit'
                result.links.new(bound.outputs['Valid'],gate.inputs['Switch'])
                result.links.new(record.outputs['Geometry'],gate.inputs['True'])
                geometry = gate.outputs['Output']
            for socket in destinations: result.links.new(geometry, socket)
            result.nodes.remove(old); changed.append(tree.name)
        memo[tree.as_pointer()] = result
        return result

    candidate = clone(original)
    if not changed: return original
    return _checked(original, candidate, library, name, changed)


def build(original, library):
    if not supports(original):
        raise ValueError('Pattern fitting requires a framed original-port or compound patch')
    identity = hashlib.sha256((original.name+'|'+library.name).encode()).hexdigest()[:16]
    name = 'Prochitecture Streets / Checked prepared pattern v1 / '+identity
    if name in bpy.data.node_groups: return bpy.data.node_groups[name]
    memo = {}; changed = []

    def clone(tree):
        if tree.as_pointer() in memo: return memo[tree.as_pointer()]
        if tree.name.startswith('Prochitecture Streets / Pinned curved quad descent v1'):
            shim = c.Graph('Prochitecture Streets / Prepared pattern adapter / '+identity)
            for s in tree.interface.items_tree:
                if s.item_type == 'SOCKET':
                    shim.socket(s.name, s.socket_type, s.in_out, default=getattr(s, 'default_value', None))
            inp = shim.node('NodeGroupInput'); out = shim.node('NodeGroupOutput')
            call = shim.node('GeometryNodeGroup'); call.node_tree = library
            shim.bind(inp.outputs['Geometry'], call.inputs['Geometry'])
            # Empty on a topology mismatch or rejected planar fit. The complete
            # caller, including its height/footprint checks, decides acceptance.
            shim.bind(call.outputs['Geometry'], out.inputs['Geometry'])
            result = shim.g; changed.append(tree.name)
        else:
            children = [(n.name, clone(n.node_tree)) for n in tree.nodes if n.type == 'GROUP' and n.node_tree]
            replacements = [(key, child) for key, child in children if child != tree.nodes[key].node_tree]
            result = tree.copy() if replacements else tree
            if replacements:
                result.name = 'Prochitecture Streets / Pattern dependency / '+hashlib.sha256(
                    (tree.name+'|'+identity).encode()).hexdigest()[:16]
                for key, child in replacements: assign_group(result.nodes[key], child)
        memo[tree.as_pointer()] = result
        return result

    candidate = clone(original)
    if not changed: raise ValueError('No shared quad descent dependency found')
    return _checked(original, candidate, library, name, changed)


def _checked(original, candidate, library, name, changed):
    """Keep the complete original surface checks and immutable fallback."""
    g = c.Graph(name)
    sockets = [s for s in original.interface.items_tree if s.item_type == 'SOCKET']
    for s in sockets: g.socket(s.name, s.socket_type, s.in_out, default=getattr(s, 'default_value', None))
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    fast = g.node('GeometryNodeGroup', 'Pattern fit with all original patch guards'); fast.node_tree = candidate
    fallback = g.node('GeometryNodeGroup', 'Original patch after pattern mismatch or rejection'); fallback.node_tree = original
    for s in sockets:
        if s.in_out == 'INPUT':
            for call in (fast, fallback): g.bind(inp.outputs[s.name], call.inputs[s.name])
    for s in sockets:
        if s.in_out != 'OUTPUT': continue
        kind = {'NodeSocketBool':'BOOLEAN', 'NodeSocketGeometry':'GEOMETRY'}[s.socket_type]
        value = c.choose(g, fast.outputs['Valid'], fast.outputs[s.name], fallback.outputs[s.name], kind)
        if s.name in ('Geometry', 'Inspection Geometry', 'Status'):
            value = c._store(g, value, 'st_cq_pattern_candidate', fast.outputs['Valid'], 'BOOLEAN')
        g.bind(value, out.inputs[s.name])
    g.g['st_pattern_original'] = original.name
    g.g['st_pattern_catalogue'] = library.name
    g.g['st_pattern_dependencies'] = sorted(set(changed))
    return g.g
